import{_ as e,o,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Detalhamento do Sistema de Agendamento da Jurisprudência Espacial","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0013-空间法理调度体系详解.md","filePath":"pt/0013-空间法理调度体系详解.md"}'),r={name:"pt/0013-空间法理调度体系详解.md"};function t(d,a,n,c,l,p){return o(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="detalhamento-do-sistema-de-agendamento-da-jurisprudencia-espacial" tabindex="-1">Detalhamento do Sistema de Agendamento da Jurisprudência Espacial <a class="header-anchor" href="#detalhamento-do-sistema-de-agendamento-da-jurisprudencia-espacial" aria-label="Permalink to &quot;Detalhamento do Sistema de Agendamento da Jurisprudência Espacial&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>13</td></tr><tr><td>Módulo</td><td>Leis do Universo e Sistemas de Cultivo</td></tr><tr><td>Palavras-chave</td><td>Jurisprudência Espacial, Agendamento de Leis, Travessia de Planos, Espaço Isolado, Três Bases Originais</td></tr></tbody></table><h2 id="i-visao-geral-do-sistema" tabindex="-1">I. Visão Geral do Sistema <a class="header-anchor" href="#i-visao-geral-do-sistema" aria-label="Permalink to &quot;I. Visão Geral do Sistema&quot;">​</a></h2><p>O Sistema de Agendamento da Jurisprudência Espacial é o terceiro dos trezentos sistemas de cultivo originais, ocupando o terceiro lugar entre as &quot;Três Bases Originais&quot;, e é a base de todos os sistemas de cultivo e aplicações tecnológicas que envolvem operações de espaço, dimensão e plano. Este sistema tem como núcleo a &quot;compreensão e o agendamento das leis espaciais&quot;, enfatizando a percepção precisa e o controle ordenado da jurisprudência espacial, em vez de um rasgamento e destruição espaciais simples e grosseiros. O Sistema de Agendamento da Jurisprudência Espacial é a base de cultivo para aplicações importantes como interação entre planos, construção de espaços isolados, tecnologia de espelhos replicantes e manutenção de âncoras, desempenhando um papel insubstituível na construção de infraestrutura da civilização simbiótica.</p><p>O Sistema de Agendamento da Jurisprudência Espacial é adequado para cultivadores com forte percepção espacial, pensamento lógico rigoroso e que valorizam a precisão e a ordem. Os cultivadores deste sistema são o grupo de talentos técnicos mais importantes da civilização simbiótica, responsáveis por tarefas cruciais como construção de âncoras, manutenção de canais entre planos, gestão de espaços isolados e construção de espaços arqueológicos.</p><h2 id="ii-principio-central-do-sistema" tabindex="-1">II. Princípio Central do Sistema <a class="header-anchor" href="#ii-principio-central-do-sistema" aria-label="Permalink to &quot;II. Princípio Central do Sistema&quot;">​</a></h2><p>O princípio central do Sistema de Agendamento da Jurisprudência Espacial é &quot;o espaço é jurisprudência, o agendamento é ordem&quot;, que pode ser compreendido a partir dos três níveis a seguir:</p><h3 id="_2-1-a-essencia-jurisprudencial-do-espaco" tabindex="-1">2.1 A Essência Jurisprudencial do Espaço <a class="header-anchor" href="#_2-1-a-essencia-jurisprudencial-do-espaco" aria-label="Permalink to &quot;2.1 A Essência Jurisprudencial do Espaço&quot;">​</a></h3><p>Na visão de mundo do Heng Yuan Zhou, o espaço não é um recipiente vazio, mas uma estrutura ordenada composta por uma série de regras jurisprudenciais. Atributos como dimensão, distância, direção, curvatura e estabilidade do espaço são todos determinados pelas regras jurisprudenciais espaciais subjacentes. Compreender a essência do espaço significa compreender o mecanismo de funcionamento dessas regras jurisprudenciais.</p><p>A jurisprudência espacial pode ser dividida em três níveis: jurisprudência básica (determina os atributos básicos do espaço, como estrutura tridimensional, definição de distância, etc.), jurisprudência mutável (determina a variabilidade do espaço, como dobramento espacial, mudança de curvatura, etc.), jurisprudência original (determina a criação e destruição do espaço, como formação e colapso de planos, etc.). O cultivo do Sistema de Agendamento da Jurisprudência Espacial começa com a compreensão da jurisprudência básica, aprofundando-se gradualmente na jurisprudência mutável e na jurisprudência original.</p><h3 id="_2-2-o-metodo-central-do-agendamento" tabindex="-1">2.2 O Método Central do Agendamento <a class="header-anchor" href="#_2-2-o-metodo-central-do-agendamento" aria-label="Permalink to &quot;2.2 O Método Central do Agendamento&quot;">​</a></h3><p>&quot;Agendamento&quot; é a metodologia central do Sistema de Agendamento da Jurisprudência Espacial. Ao contrário do &quot;rasgamento espacial&quot; no cultivo de pilhagem, o agendamento não destrói a estrutura espacial por violência, mas realiza ajustes e controles ordenados do espaço por meio da compreensão e do cumprimento da jurisprudência espacial.</p><p>Os métodos centrais do agendamento incluem:</p><ul><li><strong>Percepção Jurisprudencial</strong>: perceber o estado de funcionamento das regras jurisprudenciais no espaço, identificar a estrutura e as anomalias do espaço</li><li><strong>Orientação Jurisprudencial</strong>: por meio da própria energia e consciência, orientar a jurisprudência espacial a funcionar na direção esperada</li><li><strong>Ressonância Jurisprudencial</strong>: gerar ressonância com a jurisprudência espacial, ampliar o efeito e o alcance do agendamento</li><li><strong>Estabilização Jurisprudencial</strong>: estabilizar os resultados do agendamento em estruturas espaciais estáveis, como espaços isolados, canais entre planos, etc.</li></ul><p>A chave do agendamento está em &quot;agir de acordo com a tendência&quot;. O cultivador não é o senhor do espaço, mas o &quot;agendador&quot; da jurisprudência espacial — por meio da compreensão e do cumprimento da jurisprudência, realiza o controle ordenado do espaço.</p><h3 id="_2-3-principios-eticos-da-operacao-espacial" tabindex="-1">2.3 Princípios Éticos da Operação Espacial <a class="header-anchor" href="#_2-3-principios-eticos-da-operacao-espacial" aria-label="Permalink to &quot;2.3 Princípios Éticos da Operação Espacial&quot;">​</a></h3><p>O Sistema de Agendamento da Jurisprudência Espacial estabeleceu rigorosos princípios éticos para operações espaciais:</p><ul><li><strong>Princípio da Intervenção Mínima</strong>: as operações no espaço devem ser o menor possível, evitando destruições desnecessárias da estrutura espacial</li><li><strong>Princípio da Recuperabilidade</strong>: todas as operações espaciais temporárias devem restaurar o estado original do espaço após a conclusão, não podendo deixar danos permanentes</li><li><strong>Princípio do Isolamento</strong>: as operações espaciais que podem gerar riscos devem ser realizadas em espaços isolados, para evitar a disseminação de riscos</li><li><strong>Princípio da Aprovação</strong>: as operações espaciais de alto nível (como travessia de planos, dobramento espacial, etc.) devem passar pela aprovação da instituição de gestão de âncoras</li></ul><h2 id="iii-divisao-de-reinos-e-caracteristicas-de-cada-fase" tabindex="-1">III. Divisão de Reinos e Características de Cada Fase <a class="header-anchor" href="#iii-divisao-de-reinos-e-caracteristicas-de-cada-fase" aria-label="Permalink to &quot;III. Divisão de Reinos e Características de Cada Fase&quot;">​</a></h2><p>O Sistema de Agendamento da Jurisprudência Espacial é dividido em cinco reinos centrais:</p><table tabindex="0"><thead><tr><th>Reino</th><th>Nome</th><th>Característica Central</th><th>Alcance de Controle Espacial</th><th>Habilidade Marcante</th></tr></thead><tbody><tr><td>Primeiro Reino</td><td>Reconhecimento do Espaço</td><td>Percebe inicialmente a existência da jurisprudência espacial, capaz de identificar a estrutura básica do espaço</td><td>Alcance de percepção de cem metros</td><td>Percepção Espacial: pode perceber o estado jurisprudencial e as anomalias do espaço circundante</td></tr><tr><td>Segundo Reino</td><td>Controle do Espaço</td><td>Capaz de realizar controle básico do espaço, como deslocamento espacial de curta distância</td><td>Alcance de controle de dez metros</td><td>Teleporte de Curta Distância: pode realizar deslocamento espacial dentro de um alcance de dez metros</td></tr><tr><td>Terceiro Reino</td><td>Transformação do Espaço</td><td>Capaz de alterar atributos locais do espaço, como dobramento espacial, ajuste de curvatura</td><td>Alcance de controle de cem metros</td><td>Dobramento Espacial: pode dobrar uma distância de cem metros a um passo de distância</td></tr><tr><td>Quarto Reino</td><td>Espaço Jurisprudencial</td><td>Capaz de construir estruturas espaciais estáveis, como espaços isolados, espaços de armazenamento</td><td>Alcance de controle de quilômetros</td><td>Construção de Espaço Isolado: pode criar espaços independentes estáveis para cultivo ou experimentos</td></tr><tr><td>Quinto Reino</td><td>Espaço Original</td><td>Toca a jurisprudência original do espaço, capaz de realizar travessia de planos e construção de canais entre planos</td><td>Alcance de controle entre planos</td><td>Travessia de Planos: pode realizar travessia estável entre planos com o suporte de âncoras</td></tr></tbody></table><p>A superação de cada reino requer a aprovação no &quot;Exame de Jurisprudência Espacial&quot;: são avaliados a profundidade de compreensão do cultivador sobre a jurisprudência espacial, a precisão e estabilidade do controle espacial, e o cumprimento da ética de operação espacial; somente quando os três itens atingirem o padrão é que a elevação do reino pode ser confirmada.</p><h2 id="iv-metodos-centrais-de-cultivo-do-sistema" tabindex="-1">IV. Métodos Centrais de Cultivo do Sistema <a class="header-anchor" href="#iv-metodos-centrais-de-cultivo-do-sistema" aria-label="Permalink to &quot;IV. Métodos Centrais de Cultivo do Sistema&quot;">​</a></h2><h3 id="_4-1-metodo-de-cultivo-da-percepcao-jurisprudencial" tabindex="-1">4.1 Método de Cultivo da Percepção Jurisprudencial <a class="header-anchor" href="#_4-1-metodo-de-cultivo-da-percepcao-jurisprudencial" aria-label="Permalink to &quot;4.1 Método de Cultivo da Percepção Jurisprudencial&quot;">​</a></h3><p>A percepção jurisprudencial é a base do Sistema de Agendamento da Jurisprudência Espacial, e inclui:</p><ul><li><strong>Método de Escuta Silenciosa do Espaço</strong>: em um espaço silencioso, fechar os olhos e concentrar a mente, perceber o funcionamento sutil da jurisprudência espacial, como se estivesse &quot;ouvindo&quot; a respiração do espaço</li><li><strong>Método de Identificação de Anomalias</strong>: realizar treinamento de percepção em áreas com anomalias espaciais (como fissuras espaciais, anomalias de curvatura, etc.), aprimorar a capacidade de identificar anomalias espaciais</li><li><strong>Método de Percepção Multidimensional</strong>: treinar gradualmente a percepção de estruturas espaciais além das três dimensões, preparando a base para a compreensão da jurisprudência espacial de alta dimensão</li><li><strong>Método de Mapa Jurisprudencial</strong>: desenhar a estrutura jurisprudencial espacial percebida em um &quot;mapa jurisprudencial&quot; na consciência, aprimorando a cognição geral da estrutura espacial</li></ul><h3 id="_4-2-metodo-de-cultivo-do-controle-espacial" tabindex="-1">4.2 Método de Cultivo do Controle Espacial <a class="header-anchor" href="#_4-2-metodo-de-cultivo-do-controle-espacial" aria-label="Permalink to &quot;4.2 Método de Cultivo do Controle Espacial&quot;">​</a></h3><p>O controle espacial é a habilidade central do sistema, e inclui:</p><ul><li><strong>Método de Treinamento de Microoperação</strong>: começar o treinamento a partir do controle espacial de menor alcance, como dobrar um centímetro de espaço, aprimorando gradualmente a precisão e o alcance do controle</li><li><strong>Método de Cultivo de Deslocamento</strong>: começar a partir de deslocamentos espaciais de curta distância, aumentando gradualmente a distância e a complexidade do deslocamento, até alcançar o teleporte contínuo</li><li><strong>Método de Cultivo de Dobramento</strong>: treinar a capacidade de dobramento espacial, desde dobramentos lineares simples até dobramentos multidimensionais complexos</li><li><strong>Método de Cultivo de Curvatura</strong>: treinar a capacidade de ajustar a curvatura espacial; o controle de curvatura é a base da tecnologia espacial de alto nível</li></ul><h3 id="_4-3-metodo-de-cultivo-da-construcao-espacial" tabindex="-1">4.3 Método de Cultivo da Construção Espacial <a class="header-anchor" href="#_4-3-metodo-de-cultivo-da-construcao-espacial" aria-label="Permalink to &quot;4.3 Método de Cultivo da Construção Espacial&quot;">​</a></h3><p>A construção espacial é a habilidade de alto nível do sistema, e inclui:</p><ul><li><strong>Método de Construção de Espaço de Armazenamento</strong>: aprender a construir pequenos espaços de armazenamento estáveis, dominar a tecnologia de estabilização de fronteiras espaciais</li><li><strong>Método de Construção de Espaço Isolado</strong>: aprender a construir espaços independentes com efeito de isolamento, dominar a tecnologia de barreiras espaciais e isolamento de energia</li><li><strong>Método de Construção de Espaço de Cultivo</strong>: aprender a construir espaços especiais adequados para o cultivo, como salas de cultivo com fluxo temporal diferente, campos de cultivo com concentração de energia ajustável, etc.</li><li><strong>Método de Construção de Canal entre Planos</strong>: com o suporte de âncoras, aprender a construir canais estáveis conectando dois planos</li></ul><h2 id="v-aplicacoes-do-sistema-na-civilizacao-simbiotica" tabindex="-1">V. Aplicações do Sistema na Civilização Simbiótica <a class="header-anchor" href="#v-aplicacoes-do-sistema-na-civilizacao-simbiotica" aria-label="Permalink to &quot;V. Aplicações do Sistema na Civilização Simbiótica&quot;">​</a></h2><p>O Sistema de Agendamento da Jurisprudência Espacial tem aplicações amplas e importantes na civilização simbiótica:</p><h3 id="_5-1-construcao-de-infraestrutura" tabindex="-1">5.1 Construção de Infraestrutura <a class="header-anchor" href="#_5-1-construcao-de-infraestrutura" aria-label="Permalink to &quot;5.1 Construção de Infraestrutura&quot;">​</a></h3><ul><li><strong>Construção e Manutenção de Âncoras</strong>: os cultivadores de alto nível do Sistema de Agendamento da Jurisprudência Espacial são a força central na construção de âncoras, responsáveis pelo projeto e construção da estrutura espacial das âncoras</li><li><strong>Manutenção de Canais entre Planos</strong>: manter os canais espaciais que conectam os diversos planos, garantindo a estabilidade e segurança dos canais</li><li><strong>Construção de Espaços Públicos de Cultivo</strong>: construir instalações espaciais especiais como salas públicas de cultivo, salas de percepção jurisprudencial, etc.</li></ul><h3 id="_5-2-arqueologia-e-pesquisa" tabindex="-1">5.2 Arqueologia e Pesquisa <a class="header-anchor" href="#_5-2-arqueologia-e-pesquisa" aria-label="Permalink to &quot;5.2 Arqueologia e Pesquisa&quot;">​</a></h3><ul><li><strong>Arqueologia Remota por Espelhos Replicantes</strong>: os cultivadores de jurisprudência espacial participam da construção espacial da tecnologia de espelhos replicantes, fornecendo espaços remotos isolados para a arqueologia</li><li><strong>Experimentos em Espaços Isolados</strong>: fornecer espaços isolados para experimentos jurisprudenciais perigosos e experimentos de energia, evitando a disseminação de riscos</li><li><strong>Pesquisa de Espaços Antigos</strong>: pesquisar as estruturas e tecnologias espaciais deixadas por civilizações antigas</li></ul><h3 id="_5-3-aplicacoes-de-vida-cotidiana" tabindex="-1">5.3 Aplicações de Vida Cotidiana <a class="header-anchor" href="#_5-3-aplicacoes-de-vida-cotidiana" aria-label="Permalink to &quot;5.3 Aplicações de Vida Cotidiana&quot;">​</a></h3><ul><li><strong>Tecnologia de Armazenamento Espacial</strong>: fornecer aparelhos de armazenamento espacial para o povo comum, facilitando a vida diária</li><li><strong>Medicina Espacial</strong>: utilizar a tecnologia espacial para realizar operações médicas precisas, como cirurgias não invasivas, remoção de lesões internas, etc.</li><li><strong>Transporte Espacial</strong>: sistemas de transporte de curta distância baseados na tecnologia de dobramento espacial, aumentando significativamente a eficiência de deslocamento</li></ul><h3 id="_5-4-seguranca-e-defesa" tabindex="-1">5.4 Segurança e Defesa <a class="header-anchor" href="#_5-4-seguranca-e-defesa" aria-label="Permalink to &quot;5.4 Segurança e Defesa&quot;">​</a></h3><ul><li><strong>Barreiras Espaciais</strong>: construir barreiras espaciais para a proteção de instalações importantes</li><li><strong>Bloqueio Espacial</strong>: em situações de emergência, realizar bloqueio espacial em áreas específicas para evitar a disseminação de perigos</li><li><strong>Resgate Espacial</strong>: utilizar a capacidade de deslocamento espacial para realizar resgates de emergência, como a transferência rápida de pessoas de locais de desastre</li></ul><h2 id="vi-vantagens-e-limitacoes-do-sistema" tabindex="-1">VI. Vantagens e Limitações do Sistema <a class="header-anchor" href="#vi-vantagens-e-limitacoes-do-sistema" aria-label="Permalink to &quot;VI. Vantagens e Limitações do Sistema&quot;">​</a></h2><h3 id="_6-1-vantagens" tabindex="-1">6.1 Vantagens <a class="header-anchor" href="#_6-1-vantagens" aria-label="Permalink to &quot;6.1 Vantagens&quot;">​</a></h3><ul><li>Valor prático extremamente alto, é um sistema central indispensável para a construção de infraestrutura da civilização</li><li>A capacidade de controle espacial tem enormes vantagens em cenários de batalha, exploração, resgate, etc.</li><li>Os cultivadores têm alto status social, com abundantes oportunidades de emprego e desenvolvimento</li><li>Integração estreita com aplicações tecnológicas, os resultados do cultivo podem ser diretamente convertidos em produtos tecnológicos</li><li>Após o aprimoramento da capacidade de percepção espacial, também tem um papel auxiliar no cultivo de outros sistemas</li></ul><h3 id="_6-2-limitacoes" tabindex="-1">6.2 Limitações <a class="header-anchor" href="#_6-2-limitacoes" aria-label="Permalink to &quot;6.2 Limitações&quot;">​</a></h3><ul><li>Tem certos requisitos de talento para percepção espacial, nem todas as raças são adequadas para praticá-lo</li><li>O aumento do poder de batalha no estágio inicial não é óbvio, as habilidades principais tendem para o auxílio e a tecnologia</li><li>As operações espaciais de alto nível têm riscos relativamente altos, erros de operação podem levar a consequências graves como fissuras espaciais</li><li>A superação dos reinos de alto nível requer o suporte de âncoras, sendo difícil cultivar em áreas com cobertura insuficiente de âncoras</li><li>O processo de cultivo é relativamente monótono, exigindo uma grande quantidade de treinamento de controle preciso</li></ul><h2 id="vii-compatibilidade-com-outros-sistemas" tabindex="-1">VII. Compatibilidade com Outros Sistemas <a class="header-anchor" href="#vii-compatibilidade-com-outros-sistemas" aria-label="Permalink to &quot;VII. Compatibilidade com Outros Sistemas&quot;">​</a></h2><p>O Sistema de Agendamento da Jurisprudência Espacial tem boa compatibilidade com outros sistemas, especialmente:</p><ul><li>Cultivo conjunto com o Sistema de Iteração Dedutiva: pode deduzir vários modos de aplicação da jurisprudência espacial, aprimorando a precisão e a inovação do controle espacial</li><li>Cultivo conjunto com o Sistema de Ciclo de Vida: pode construir espaços especiais de ciclo de energia vital, aprimorando a eficiência do cultivo do ciclo de vida</li><li>Cultivo conjunto com sistemas do tipo Elevação de Consciência: a compreensão da jurisprudência espacial ajuda a percepção e adaptação da consciência ao espaço de alta dimensão</li><li>Cultivo conjunto com sistemas do tipo Engenharia Aplicada: a tecnologia de jurisprudência espacial é um ramo importante da engenharia jurisprudencial, o cultivo conjunto pode aprimorar significativamente a capacidade de engenharia</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O Sistema de Agendamento da Jurisprudência Espacial é a &quot;pedra angular espacial&quot; da civilização simbiótica das Âncoras. Baseando-se na profunda compreensão da jurisprudência espacial e utilizando o agendamento ordenado como método, ele fornece suporte tecnológico espacial indispensável para a interação entre planos, construção de infraestrutura, pesquisa científica e aplicações de vida cotidiana da civilização. O objetivo final do Sistema de Agendamento da Jurisprudência Espacial é fazer com que os cultivadores se tornem &quot;guardiões e construtores&quot; do espaço cósmico, e, com base na compreensão da jurisprudência espacial, construir uma rede espacial cósmica mais ordenada, mais conectada e mais segura.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Visão Geral dos Trezentos Sistemas de Cultivo Originais)</li><li>62-空间法理技术实现 (Implementação Tecnológica da Jurisprudência Espacial)</li><li>64-隔离空间构建技术 (Tecnologia de Construção de Espaços Isolados)</li></ul>',54)])])}const g=e(r,[["render",t]]);export{m as __pageData,g as default};
